import{n as e,t}from"./expand-B9sP1tsw.js";var n=[[3,1,`Which animal is often called the 'King of the Jungle'?`,`The lion`,[`The tiger`,`The elephant`,`The bear`],`Lions are called kings of the jungle, though they really live on open grasslands.`],[3,1,`How many days are there in a week?`,`Seven`,[`Five`,`Six`,`Eight`],`Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday.`],[3,1,`What colour do you get by mixing blue and yellow?`,`Green`,[`Purple`,`Orange`,`Brown`],`Blue and yellow paint make green.`],[3,1,`Which is the fastest land animal?`,`The cheetah`,[`The lion`,`The horse`,`The kangaroo`],`A cheetah can sprint at about 100 km/h for a short time.`],[3,2,`Which month comes after March?`,`April`,[`February`,`May`,`June`],`The order is January, February, March, April…`],[3,2,`What do we call a baby dog?`,`A puppy`,[`A kitten`,`A cub`,`A calf`],`A baby dog is a puppy.`],[3,2,`Which bird cannot fly but swims very well?`,`The penguin`,[`The eagle`,`The owl`,`The parrot`],`Penguins use their flipper-like wings to swim.`],[3,2,`How many colours are there in a rainbow?`,`Seven`,[`Five`,`Six`,`Nine`],`Red, orange, yellow, green, blue, indigo and violet.`],[3,2,`Which shape has three sides?`,`A triangle`,[`A square`,`A circle`,`A pentagon`],`'Tri' means three.`],[3,3,`What is the largest animal in the world?`,`The blue whale`,[`The African elephant`,`The giraffe`,`The great white shark`],`Blue whales are the biggest animals that have ever lived.`],[3,3,`Which is the tallest animal in the world?`,`The giraffe`,[`The elephant`,`The camel`,`The ostrich`],`A giraffe can be about 5 metres tall.`],[3,3,`Which instrument has black and white keys?`,`The piano`,[`The drum`,`The flute`,`The guitar`],`A standard piano has 88 black and white keys.`],[3,3,`What do bees make?`,`Honey`,[`Silk`,`Milk`,`Wax paper`],`Bees make honey from the nectar of flowers.`],[4,1,`Who painted the Mona Lisa?`,`Leonardo da Vinci`,[`Michelangelo`,`Vincent van Gogh`,`Pablo Picasso`],`Leonardo da Vinci painted the Mona Lisa about 500 years ago.`],[4,1,`Which sport is played at Wimbledon?`,`Tennis`,[`Cricket`,`Golf`,`Football`],`Wimbledon is a famous tennis tournament in London.`],[4,1,`Which animal mainly eats bamboo?`,`The giant panda`,[`The koala`,`The polar bear`,`The gorilla`],`Giant pandas eat up to 12 kg of bamboo a day.`],[4,2,`How many players are on a football (soccer) team on the pitch?`,`Eleven`,[`Nine`,`Ten`,`Twelve`],`Each team has 11 players, including the goalkeeper.`],[4,2,`The five Olympic rings represent…`,`Five continents joined together`,[`Five oceans of the world`,`Five sports of the first Games`,`Five founders of the Olympics`],`The rings stand for the world's inhabited regions united by sport.`],[4,2,`Which country gave the Statue of Liberty to the United States?`,`France`,[`England`,`Spain`,`Italy`],`France gave the statue as a gift in 1886.`],[4,2,`Which bird lays the biggest eggs of any living bird?`,`The ostrich`,[`The eagle`,`The penguin`,`The swan`],`An ostrich egg weighs about as much as two dozen chicken eggs.`],[4,3,`Which famous ship sank in 1912 after hitting an iceberg?`,`The Titanic`,[`The Lusitania`,`The Bismarck`,`The Mayflower`],`The Titanic sank on her first voyage across the Atlantic.`],[4,3,`Who invented the telephone in 1876?`,`Alexander Graham Bell`,[`Thomas Edison`,`Samuel Morse`,`Guglielmo Marconi`],`Bell was awarded the first patent for a practical telephone.`],[4,3,`Which scientist is famous for the theory of relativity?`,`Albert Einstein`,[`Isaac Newton`,`Galileo Galilei`,`Stephen Hawking`],`Einstein published his special theory of relativity in 1905.`],[4,3,`How many sides does a hexagon have?`,`Six`,[`Five`,`Seven`,`Eight`],`'Hexa' means six.`],[4,2,`Which Japanese sport features large wrestlers in a ring?`,`Sumo`,[`Judo`,`Karate`,`Kendo`],`Sumo wrestlers try to push each other out of a circular ring.`],[5,1,`What is the largest mammal that lives on land?`,`The African elephant`,[`The rhinoceros`,`The hippopotamus`,`The giraffe`],`African elephants can weigh as much as six tonnes.`],[5,1,`How many sides does an octagon have?`,`Eight`,[`Six`,`Seven`,`Ten`],`'Octo' means eight, like an octopus with eight arms.`],[5,1,`Who was the first person to walk on the Moon?`,`Neil Armstrong`,[`Buzz Aldrin`,`Yuri Gagarin`,`John Glenn`],`Neil Armstrong stepped onto the Moon on 20 July 1969.`],[5,2,`In which year did humans first land on the Moon?`,`1969`,[`1959`,`1972`,`1981`],`Apollo 11 landed on the Moon in July 1969.`],[5,2,`Who was the first human to travel into space?`,`Yuri Gagarin`,[`Neil Armstrong`,`Alan Shepard`,`Valentina Tereshkova`],`Gagarin orbited Earth in Vostok 1 on 12 April 1961.`],[5,2,`Which ancient people built the pyramids at Giza?`,`The ancient Egyptians`,[`The Romans`,`The Greeks`,`The Maya`],`The Great Pyramid was built about 4,500 years ago.`],[5,2,`Which festival of lights is celebrated by many people in India?`,`Diwali`,[`Holi`,`Eid`,`Navratri`],`Diwali celebrates the victory of light over darkness with lamps and fireworks.`],[5,2,`What do we call a scientist who studies the stars and planets?`,`An astronomer`,[`A geologist`,`A biologist`,`An archaeologist`],`Astronomers study space.`],[5,2,`How many players are in a cricket team that takes the field?`,`Eleven`,[`Nine`,`Ten`,`Twelve`],`A cricket side has 11 players.`],[5,3,`Who wrote the play 'Romeo and Juliet'?`,`William Shakespeare`,[`Charles Dickens`,`Jane Austen`,`Mark Twain`],`Shakespeare wrote it about 1595.`],[5,3,`Which country hosted the 2016 Summer Olympics?`,`Brazil`,[`China`,`The United Kingdom`,`Japan`],`The 2016 Games were held in Rio de Janeiro.`],[5,3,`Which language has the most native speakers in the world?`,`Mandarin Chinese`,[`English`,`Spanish`,`Hindi`],`More people grow up speaking Mandarin than any other language.`],[5,3,`Which scientist, according to the famous story, was inspired by a falling apple?`,`Isaac Newton`,[`Albert Einstein`,`Galileo Galilei`,`Charles Darwin`],`Newton developed the theory of gravity in the 1600s.`],[5,3,`Which inventor is best known for the practical electric light bulb?`,`Thomas Edison`,[`Nikola Tesla`,`Alexander Graham Bell`,`James Watt`],`Edison's team made a long-lasting bulb in 1879.`],[6,1,`Which ancient people built the city of Machu Picchu?`,`The Inca`,[`The Aztecs`,`The Maya`,`The Romans`],`Machu Picchu was built in the Andes mountains of Peru in the 1400s.`],[6,1,`Who painted 'The Starry Night'?`,`Vincent van Gogh`,[`Claude Monet`,`Rembrandt`,`Salvador Dalí`],`Van Gogh painted it in 1889.`],[6,1,`Which is the national animal of India?`,`The Bengal tiger`,[`The lion`,`The elephant`,`The peacock`],`India's national animal is the Bengal tiger. The peacock is its national bird, and lions appear on its state emblem.`],[6,2,`Who was the first President of the United States?`,`George Washington`,[`Abraham Lincoln`,`Thomas Jefferson`,`John Adams`],`Washington took office in 1789.`],[6,2,`Who led India's non-violent movement for independence?`,`Mahatma Gandhi`,[`Winston Churchill`,`Nelson Mandela`,`Napoleon`],`Gandhi's peaceful protests, like the Salt March, inspired millions.`],[6,2,`Who invented the World Wide Web?`,`Tim Berners-Lee`,[`Bill Gates`,`Steve Jobs`,`Alan Turing`],`He proposed the web in 1989 while working at CERN.`],[6,2,`What is the currency of Japan?`,`The yen`,[`The won`,`The yuan`,`The rupee`],`Japan uses the yen (¥).`],[6,2,`Which scientist discovered penicillin?`,`Alexander Fleming`,[`Louis Pasteur`,`Marie Curie`,`Jonas Salk`],`Fleming noticed mould killing bacteria in 1928.`],[6,2,`What is the official language of Brazil?`,`Portuguese`,[`Spanish`,`English`,`French`],`Brazil was once a Portuguese colony.`],[6,3,`In which year did World War II end?`,`1945`,[`1939`,`1918`,`1950`],`World War II ended in 1945.`],[6,3,`Which ancient civilisation was ruled by Emperor Augustus?`,`Rome`,[`Greece`,`Egypt`,`Persia`],`Augustus became the first Roman emperor in 27 BCE.`],[6,3,`What is the currency of the United Kingdom?`,`The pound sterling`,[`The euro`,`The dollar`,`The franc`],`The UK uses the pound (£).`],[6,3,`Who is credited with developing the first successful polio vaccine?`,`Jonas Salk`,[`Louis Pasteur`,`Edward Jenner`,`Alexander Fleming`],`Salk's vaccine was announced in 1955.`],[6,3,`What does the 'E' in UNESCO stand for?`,`Educational`,[`Economic`,`Environmental`,`Energy`],`UNESCO is the United Nations Educational, Scientific and Cultural Organization.`],[6,3,`Which explorer sailed from Spain in 1492 and reached the Americas?`,`Christopher Columbus`,[`Marco Polo`,`Ferdinand Magellan`,`Vasco da Gama`],`Columbus landed in the Caribbean in October 1492.`],[7,1,`Who wrote the 'Harry Potter' books?`,`J.K. Rowling`,[`Roald Dahl`,`C.S. Lewis`,`Enid Blyton`],`The first book was published in 1997.`],[7,1,`What is the largest organ of the human body?`,`The skin`,[`The liver`,`The heart`,`The brain`],`Skin protects the body and covers about two square metres.`],[7,2,`Who suggested that the Earth orbits the Sun (published in 1543)?`,`Nicolaus Copernicus`,[`Galileo Galilei`,`Johannes Kepler`,`Ptolemy`],`Copernicus put the Sun, not the Earth, at the centre.`],[7,2,`The Industrial Revolution began in which country?`,`Great Britain`,[`France`,`Germany`,`The United States`],`It began in Britain in the 1700s with machines and steam power.`],[7,2,`What does NASA stand for?`,`National Aeronautics and Space Administration`,[`National Air and Space Academy`,`North American Space Agency`,`National Astronomy and Satellite Association`],`NASA was founded in 1958.`],[7,2,`Which Greek city-state was famous for its warriors?`,`Sparta`,[`Athens`,`Corinth`,`Thebes`],`Spartan boys trained as soldiers from a young age.`],[7,2,`Which Indian scientist won the 1930 Nobel Prize in Physics?`,`C. V. Raman`,[`Homi Bhabha`,`S. N. Bose`,`Vikram Sarabhai`],`Raman won for discovering how light scatters, now called the Raman effect.`],[7,2,`What is the study of ancient remains and objects called?`,`Archaeology`,[`Geology`,`Zoology`,`Astronomy`],`Archaeologists dig up and study objects from the past.`],[7,3,`What was the first artificial satellite, launched in 1957?`,`Sputnik 1`,[`Explorer 1`,`Vostok 1`,`Apollo 11`],`The Soviet Union launched Sputnik 1 on 4 October 1957.`],[7,3,`Who designed the Analytical Engine, an early idea for a computer?`,`Charles Babbage`,[`Alan Turing`,`John von Neumann`,`Bill Gates`],`Babbage designed it in the 1830s.`],[7,3,`Who was the first woman to win a Nobel Prize?`,`Marie Curie`,[`Rosalind Franklin`,`Mother Teresa`,`Florence Nightingale`],`Marie Curie won the 1903 Nobel Prize in Physics.`],[7,3,`Which country was the Renaissance born in?`,`Italy`,[`England`,`Spain`,`Germany`],`The Renaissance began in Italian cities like Florence.`],[7,3,`Who painted the ceiling of the Sistine Chapel?`,`Michelangelo`,[`Raphael`,`Leonardo da Vinci`,`Donatello`],`Michelangelo painted it between 1508 and 1512.`],[7,3,`Who was the first woman in space?`,`Valentina Tereshkova`,[`Sally Ride`,`Kalpana Chawla`,`Mae Jemison`],`Tereshkova flew on Vostok 6 in 1963.`],[8,1,`Which country is the Taj Mahal in?`,`India`,[`Pakistan`,`Bangladesh`,`Iran`],`The Taj Mahal is in Agra, India.`],[8,1,`What does GPS stand for?`,`Global Positioning System`,[`General Position Signal`,`Global Planet Scanner`,`Geographic Pointing Service`],`GPS uses satellites to work out where you are.`],[8,1,`Who developed the laws of motion and universal gravitation?`,`Isaac Newton`,[`Albert Einstein`,`Galileo Galilei`,`Johannes Kepler`],`Newton published them in 1687.`],[8,2,`Which war was fought from 1914 to 1918?`,`World War I`,[`World War II`,`The Cold War`,`The Crimean War`],`World War I lasted from 1914 to 1918.`],[8,2,`Which document signed in 1215 limited the power of the English king?`,`The Magna Carta`,[`The Bill of Rights`,`The Declaration of Independence`,`The Domesday Book`],`Magna Carta means 'Great Charter'.`],[8,2,`Which organisation was founded in 1945 to promote international peace?`,`The United Nations`,[`The League of Nations`,`NATO`,`The European Union`],`The UN was created after World War II.`],[8,2,`Who wrote 'The Diary of a Young Girl'?`,`Anne Frank`,[`Malala Yousafzai`,`Helen Keller`,`Rosa Parks`],`Anne Frank wrote her diary while hiding during World War II.`],[8,2,`Who discovered the structure of DNA in 1953 with Francis Crick?`,`James Watson`,[`Gregor Mendel`,`Louis Pasteur`,`Linus Pauling`],`Their model relied on X-ray images by Rosalind Franklin.`],[8,3,`Who was the first Prime Minister of independent India?`,`Jawaharlal Nehru`,[`Mahatma Gandhi`,`Sardar Patel`,`Rajendra Prasad`],`Nehru took office on 15 August 1947.`],[8,3,`Which treaty ended the First World War with Germany in 1919?`,`The Treaty of Versailles`,[`The Treaty of Paris`,`The Treaty of Tordesillas`,`The Treaty of Vienna`],`It was signed at the Palace of Versailles near Paris.`],[8,3,`Who wrote 'On the Origin of Species' in 1859?`,`Charles Darwin`,[`Alfred Wallace`,`Gregor Mendel`,`Thomas Huxley`],`Darwin explained evolution by natural selection.`],[8,3,`The French Revolution began in which year?`,`1789`,[`1776`,`1804`,`1815`],`The storming of the Bastille happened on 14 July 1789.`],[8,3,`Which ancient writing system was developed by the Sumerians?`,`Cuneiform`,[`Hieroglyphics`,`Runes`,`Braille`],`Cuneiform used wedge-shaped marks pressed into clay.`],[8,3,`Which ancient wonder stood in the harbour of Alexandria, Egypt?`,`The Lighthouse (Pharos)`,[`The Hanging Gardens`,`The Colossus`,`The Temple of Artemis`],`The Pharos was one of the tallest man-made structures of its time.`]],r=[[[3,1,`history`,`On what did the ancient Egyptians often write, using a material made from a river plant?`,`Papyrus`,[`Bamboo strips`,`Cotton cloth`,`Rice paper`],`Papyrus was made from reeds that grew along the Nile.`],[3,2,`history`,`What did people use for light at night before electric lamps?`,`Candles and oil lamps`,[`Battery torches`,`Neon signs`,`Television screens`],`For thousands of years, flames from candles and oil lamps were the main light after dark.`],[3,3,`history`,`Which animal did farmers tame long ago to pull ploughs and carts?`,`The ox`,[`The tiger`,`The wolf`,`The crocodile`],`Oxen are strong, calm cattle, still used for ploughing in many places.`],[3,2,`history`,`Dinosaurs and people lived at the same time.`,`False`,[`True`],`The great dinosaurs died out about 66 million years ago, long before the first humans.`],[4,1,`history`,`Who were the pharaohs?`,`The kings of ancient Egypt`,[`The priests of ancient Rome`,`The soldiers of ancient China`,`The farmers of ancient India`],`Pharaohs were seen as god-kings; many were buried in pyramids or rock-cut tombs.`],[4,2,`history`,`What was the Silk Road?`,`A network of trade routes linking China with the West`,[`A road paved with silk in Rome`,`A river in ancient India`,`A wall built to keep out invaders`],`Silk, spices, paper and ideas travelled along the Silk Road for centuries.`],[4,2,`history`,`Which ancient people held the first Olympic Games?`,`The ancient Greeks`,[`The ancient Egyptians`,`The Romans`,`The Vikings`],`The Games were held at Olympia in Greece from 776 BC.`],[4,3,`history`,`Who were knights in the Middle Ages?`,`Soldiers in armour who fought on horseback`,[`Farmers who worked at night`,`Monks who copied books by hand`,`Sailors who explored the oceans`],`Knights served a lord or king and followed a code of conduct called chivalry.`],[4,2,`history`,`Some roads built by the ancient Romans are still used today.`,`True`,[`False`],`Roman roads were built in layers of stone so well that parts still carry traffic.`],[5,1,`history`,`Who was Cleopatra?`,`The last active ruler of Ptolemaic Egypt`,[`The first emperor of ancient Rome`,`A Greek goddess of wisdom`,`A queen of the Persian Empire`],`Cleopatra VII ruled Egypt until 30 BC, when it became part of the Roman Empire.`],[5,1,`history`,`The Vikings came mainly from which part of Europe?`,`Scandinavia`,[`Spain and Portugal`,`Greece`,`Italy`],`Vikings from what are now Norway, Sweden and Denmark raided, traded and settled across Europe.`],[5,2,`history`,`Which great Mughal emperor, who ruled from 1556 to 1605, welcomed people of many faiths to his court?`,`Akbar`,[`Babur`,`Aurangzeb`,`Shah Jahan`],`Akbar, grandson of Babur, was known for his tolerance and his interest in many religions.`],[5,3,`history`,`What was the Great Wall of China mainly built for?`,`To protect against invaders from the north`,[`To hold back the floods`,`To mark out a race track`,`To store grain for the winter`],`Walls were built and rebuilt over many centuries along China's northern border.`],[5,2,`history`,`The Mughal emperor Shah Jahan had the Taj Mahal built.`,`True`,[`False`],`Shah Jahan built it in memory of his wife Mumtaz Mahal; work began in 1632.`],[6,1,`history`,`Which civilisation built the cities of Mohenjo-daro and Harappa?`,`The Indus Valley Civilisation`,[`The Maya`,`The Aztecs`,`The ancient Greeks`],`These planned cities, with drains and baths, flourished about 4,500 years ago.`],[6,2,`history`,`Which emperor of India's Maurya dynasty turned to Buddhism after the bloody Kalinga war?`,`Ashoka`,[`Akbar`,`Chandragupta Maurya`,`Harsha`],`Ashoka's edicts, carved on rocks and pillars, preached non-violence. His grandfather Chandragupta founded the dynasty.`],[6,2,`history`,`What does the word Renaissance, used for Europe's great revival of art and learning, mean?`,`Rebirth`,[`Revolution`,`Empire`,`Discovery`],`From the 14th to 17th centuries, artists and thinkers rediscovered ancient Greek and Roman ideas.`],[6,3,`history`,`The Battle of Plassey in 1757 gave control of Bengal to whom?`,`The British East India Company`,[`The Mughal emperor`,`The Portuguese`,`The French`],`Robert Clive's victory over Nawab Siraj ud-Daulah began British rule in Bengal.`],[6,3,`history`,`The Black Death was a deadly plague in the 14th century.`,`True`,[`False`],`It killed a huge share of the people of Europe, Asia and North Africa in the 1340s and 1350s.`],[7,1,`history`,`Who was the first emperor of a unified China?`,`Qin Shi Huang`,[`Kublai Khan`,`Genghis Khan`,`Confucius`],`He united China in 221 BC; his tomb is guarded by the Terracotta Army.`],[7,1,`history`,`Which Mongol leader founded the largest connected land empire in history?`,`Genghis Khan`,[`Kublai Khan`,`Tamerlane`,`Attila the Hun`],`Genghis Khan's empire, expanded by his successors, stretched from Korea to Eastern Europe.`],[7,2,`history`,`In which year did the partition of British India create India and Pakistan?`,`1947`,[`1857`,`1905`,`1971`],`In August 1947 British rule ended and the subcontinent was divided; East Bengal became East Pakistan.`],[7,2,`history`,`What was the aim of the Language Movement of 1952?`,`To make Bangla a state language of Pakistan`,[`To teach English in every school`,`To change the official calendar`,`To stop new taxes on rice`],`Students died in Dhaka on 21 February 1952; Bangla was later recognised as a state language.`],[7,3,`history`,`Which uprising against the East India Company began in 1857?`,`The Sepoy Mutiny (Indian Rebellion)`,[`The Boston Tea Party`,`The Language Movement`,`The French Revolution`],`After it, the British Crown took direct control of India from the Company.`],[7,2,`history`,`Paper was first made in ancient China.`,`True`,[`False`],`Chinese records credit Cai Lun with improving papermaking around AD 105.`],[8,1,`history`,`In which year did the Berlin Wall fall?`,`1989`,[`1945`,`1961`,`1991`],`The wall, built in 1961, divided Berlin until crowds crossed it in November 1989.`],[8,1,`history`,`What name is given to the long rivalry, from about 1947 to 1991, between the USA and the Soviet Union?`,`The Cold War`,[`The Hundred Years' War`,`The Great War`,`The Thirty Years' War`],`The two superpowers competed in weapons, space and influence without fighting each other directly.`],[8,2,`history`,`Which city was the capital of the Ottoman Empire for most of its history?`,`Constantinople (Istanbul)`,[`Cairo, on the Nile`,`Baghdad, on the Tigris`,`Athens, in Greece`],`The Ottomans captured Constantinople in 1453 and ruled from there until the empire ended.`],[8,2,`history`,`What did the Universal Declaration of Human Rights of 1948 set out?`,`Basic rights that belong to every person`,[`The rules of world football`,`The borders of Europe`,`The price of oil`],`It was adopted by the United Nations after the Second World War.`],[8,3,`history`,`The Mughal Empire was founded by Babur in 1526.`,`True`,[`False`],`Babur won the First Battle of Panipat in 1526 and founded the empire.`],[3,1,`inventions`,`What did the Wright brothers build and fly in 1903?`,`The first powered aeroplane`,[`The first car`,`The first rocket`,`The first hot-air balloon`],`Orville and Wilbur Wright's first flight lasted 12 seconds.`],[4,1,`inventions`,`Who built a printing press with movable metal type in Europe around 1440?`,`Johannes Gutenberg`,[`Leonardo da Vinci`,`Galileo Galilei`,`William Caxton`],`Gutenberg's press made books much cheaper. Caxton later brought printing to England.`],[4,2,`inventions`,`What did Louis Braille invent?`,`A system of raised dots that blind people read by touch`,[`A kind of telescope for night skies`,`A musical instrument with strings`,`A machine for sewing clothes`],`Braille, himself blind, created his system in the 1820s, when he was a teenager.`],[4,3,`inventions`,`Which invention from ancient China helped sailors find their direction?`,`The magnetic compass`,[`The telescope`,`The steam engine`,`The sundial`],`A magnetised needle points north-south, so ships could navigate under cloudy skies.`],[5,1,`inventions`,`Which American is said to have flown a kite in a storm to show that lightning is electricity?`,`Benjamin Franklin`,[`Thomas Edison`,`George Washington`,`Albert Einstein`],`Franklin's experiments led him to invent the lightning rod.`],[5,2,`inventions`,`What did Karl Benz build in 1885–86?`,`One of the first petrol-powered cars`,[`The first aeroplane`,`The first steam train`,`The first bicycle`],`Benz's three-wheeled Motorwagen is often called the first practical car.`],[5,3,`inventions`,`Who made the first successful vaccine, against smallpox, in 1796?`,`Edward Jenner`,[`Louis Pasteur`,`Jonas Salk`,`Alexander Fleming`],`Jenner used material from cowpox; smallpox was finally wiped out in 1980.`],[5,2,`inventions`,`The first electronic computers filled whole rooms.`,`True`,[`False`],`Machines such as ENIAC (1945) weighed tonnes and used thousands of glass valves.`],[6,1,`inventions`,`Which Italian scientist improved the telescope and saw the moons of Jupiter?`,`Galileo Galilei`,[`Isaac Newton`,`Marco Polo`,`Leonardo da Vinci`],`In 1610 Galileo saw four moons circling Jupiter, evidence that not everything orbits Earth.`],[6,2,`inventions`,`Which scientist born in present-day Bangladesh did pioneering work on radio waves and on how plants respond?`,`Jagadish Chandra Bose`,[`C. V. Raman`,`Satyendra Nath Bose`,`Homi Bhabha`],`J. C. Bose, born in 1858 in Mymensingh, also invented the crescograph to measure plant growth.`],[6,3,`inventions`,`What did Louis Pasteur show about germs?`,`Germs cause disease and can be killed by heating`,[`Germs are good for every wound`,`Germs only live in cold places`,`Germs are made by the Sun`],`Heating milk to kill germs is called pasteurisation after him.`],[7,1,`inventions`,`Who discovered X-rays in 1895?`,`Wilhelm Röntgen`,[`Marie Curie`,`Thomas Edison`,`Niels Bohr`],`Röntgen won the first Nobel Prize in Physics, in 1901, for the discovery.`],[7,2,`inventions`,`Who invented dynamite and left his fortune to found the Nobel Prizes?`,`Alfred Nobel`,[`Albert Einstein`,`Ernest Rutherford`,`Michael Faraday`],`The first Nobel Prizes were awarded in 1901.`],[7,3,`inventions`,`Which physicist from Bengal worked on quantum statistics with Albert Einstein, giving his name to the 'boson'?`,`Satyendra Nath Bose`,[`Jagadish Chandra Bose`,`Meghnad Saha`,`Abdus Salam`],`S. N. Bose did this work in 1924 while teaching at the University of Dhaka.`],[8,1,`inventions`,`Who arranged the elements into a periodic table in 1869?`,`Dmitri Mendeleev`,[`John Dalton`,`Antoine Lavoisier`,`Robert Boyle`],`Mendeleev left gaps for elements not yet discovered, and correctly predicted their properties.`],[8,2,`inventions`,`Who discovered the electron in 1897?`,`J. J. Thomson`,[`Ernest Rutherford`,`James Chadwick`,`Niels Bohr`],`Thomson found that cathode rays are made of tiny negative particles: electrons.`],[8,3,`inventions`,`Which inventor developed alternating-current motors and was a rival of Thomas Edison?`,`Nikola Tesla`,[`Alexander Graham Bell`,`Guglielmo Marconi`,`James Watt`],`Tesla's AC systems power most of the world's electricity grids today.`]],[[3,2,`people`,`Which nurse, called 'the Lady with the Lamp', made army hospitals cleaner and safer in the 1850s?`,`Florence Nightingale`,[`Mary Seacole`,`Clara Barton`,`Edith Cavell`],`Nightingale's work in the Crimean War led her to found modern nursing.`],[4,1,`people`,`Which US president led his country through its Civil War and worked to end slavery?`,`Abraham Lincoln`,[`George Washington`,`Thomas Jefferson`,`Theodore Roosevelt`],`Lincoln was president from 1861 until he was assassinated in 1865.`],[4,2,`people`,`Which nun won the Nobel Peace Prize in 1979 for her work with the poor and sick in Kolkata?`,`Mother Teresa`,[`Florence Nightingale`,`Malala Yousafzai`,`Begum Rokeya`],`Mother Teresa founded the Missionaries of Charity in Kolkata in 1950.`],[4,3,`people`,`Who led the first expedition to reach the South Pole, in 1911?`,`Roald Amundsen`,[`Robert Falcon Scott`,`Ernest Shackleton`,`Edmund Hillary`],`Amundsen's Norwegian team arrived about five weeks before Scott's British team.`],[4,2,`people`,`Leonardo da Vinci was a painter and also an inventor.`,`True`,[`False`],`His notebooks are full of designs for flying machines, bridges and weapons.`],[5,1,`people`,`Which two climbers were the first to reach the top of Mount Everest, in 1953?`,`Edmund Hillary and Tenzing Norgay`,[`Neil Armstrong and Buzz Aldrin`,`Roald Amundsen and Robert Scott`,`Lewis and Clark`],`Hillary was from New Zealand and Tenzing Norgay was a Sherpa from Nepal.`],[5,2,`people`,`Which Moroccan traveller of the 14th century journeyed across Africa and Asia, even reaching Bengal?`,`Ibn Battuta`,[`Marco Polo`,`Zheng He`,`Vasco da Gama`],`Ibn Battuta travelled for about 30 years and described his journeys in a famous book, the Rihla.`],[5,3,`people`,`Which leader of the US civil rights movement gave the 'I Have a Dream' speech in 1963?`,`Martin Luther King Jr.`,[`Malcolm X`,`Barack Obama`,`Frederick Douglass`],`King campaigned peacefully for equal rights and won the Nobel Peace Prize in 1964.`],[6,1,`people`,`Which Bangladeshi economist won the Nobel Peace Prize in 2006, together with the Grameen Bank?`,`Muhammad Yunus`,[`Amartya Sen`,`Fazle Hasan Abed`,`Abdus Salam`],`The prize honoured microcredit: small loans that help people, especially women, start businesses.`],[6,2,`people`,`Which Bengali writer and pioneer of girls' education wrote the story 'Sultana's Dream'?`,`Begum Rokeya`,[`Sufia Kamal`,`Pritilata Waddedar`,`Jahanara Imam`],`Rokeya Sakhawat Hossain (1880–1932) founded a school for Muslim girls in Kolkata.`],[6,3,`people`,`In 1913 Rabindranath Tagore became the first non-European to win which prize?`,`The Nobel Prize in Literature`,[`The Nobel Peace Prize`,`An Olympic gold medal`,`The Pulitzer Prize`],`He won for 'Gitanjali', a collection of poems.`],[7,1,`people`,`Which Pakistani campaigner for girls' education became the youngest Nobel Prize winner in 2014?`,`Malala Yousafzai`,[`Benazir Bhutto`,`Fatima Jinnah`,`Begum Rokeya`],`Malala was 17 when she shared the Nobel Peace Prize.`],[7,2,`people`,`Which Persian physician wrote 'The Canon of Medicine', used in universities for centuries?`,`Ibn Sina (Avicenna)`,[`Al-Khwarizmi`,`Ibn Battuta`,`Omar Khayyam`],`Ibn Sina lived around 980–1037 and wrote about medicine, philosophy and science.`],[7,3,`people`,`Which scientist first proposed, in 1912, that the continents drift?`,`Alfred Wegener`,[`Charles Lyell`,`James Hutton`,`Gregor Mendel`],`Wegener noticed how the coasts of Africa and South America fit together like puzzle pieces.`],[8,1,`people`,`Who became the world's first woman prime minister, in 1960?`,`Sirimavo Bandaranaike`,[`Indira Gandhi`,`Margaret Thatcher`,`Golda Meir`],`She led Sri Lanka (then Ceylon), and served as prime minister three times.`],[8,2,`people`,`Which mathematician's name gave us the word 'algorithm'?`,`Al-Khwarizmi`,[`Euclid`,`Pythagoras`,`Archimedes`],`Al-Khwarizmi worked in Baghdad in the 9th century; the word 'algebra' comes from one of his book titles.`],[8,3,`people`,`Whose X-ray photograph, 'Photo 51', helped reveal the double-helix structure of DNA?`,`Rosalind Franklin`,[`Marie Curie`,`Ada Lovelace`,`Dorothy Hodgkin`],`Franklin's image was key evidence for the DNA model published in 1953.`],[3,1,`world`,`How many months are there in a year?`,`Twelve`,[`Ten`,`Seven`,`Fifty-two`],`January to December makes twelve months; a year also has 52 weeks.`],[4,1,`world`,`What does a red cross on a white background usually stand for?`,`Medical help and care`,[`A danger zone`,`A shop`,`A school`],`The red cross is a protected symbol for medical help, especially in wars and disasters.`],[5,1,`world`,`In which city are the headquarters of the United Nations?`,`New York City`,[`Geneva`,`Paris`,`London`],`The UN headquarters stands beside the East River in New York.`],[5,2,`world`,`Which organisation leads the world's work against diseases such as malaria?`,`The World Health Organization`,[`The World Trade Organization`,`UNESCO`,`FIFA`],`The WHO, part of the United Nations, is based in Geneva.`],[5,3,`world`,`What is UNICEF mainly concerned with?`,`Children's rights and well-being`,[`Space travel`,`World trade rules`,`Football`],`UNICEF provides food, vaccines, clean water and schooling for children in need.`],[7,1,`world`,`What is the Red Crescent?`,`A humanitarian aid movement, partner of the Red Cross`,[`A badge for football champions`,`A crescent-shaped island`,`A type of moon in eclipse`],`Many countries, including Bangladesh, use the red crescent instead of the red cross.`],[7,3,`world`,`What is the Commonwealth of Nations?`,`A group of countries, most of them once part of the British Empire`,[`A single country with many cities`,`A trade deal between China and Japan`,`A group of islands in the Pacific`],`Bangladesh, India, Canada and Nigeria are among its member countries.`],[8,1,`world`,`Which part of the UN has five permanent members that can veto decisions?`,`The Security Council`,[`The General Assembly`,`UNESCO`,`The World Bank`],`The five permanent members are China, France, Russia, the United Kingdom and the United States.`],[8,2,`world`,`What is the main job of the World Trade Organization?`,`Setting rules for trade between countries`,[`Running the Olympic Games`,`Forecasting the world's weather`,`Printing the world's money`],`The WTO helps settle trade disputes between its members.`],[8,3,`world`,`What is SAARC?`,`An association of South Asian countries for regional cooperation`,[`A South American football league`,`A space agency in Asia`,`A charity for sea animals`],`The South Asian Association for Regional Cooperation was founded in Dhaka in 1985.`],[3,1,`sports`,`A basketball coach sends a team onto the court. How many of its players can play at once?`,`Five`,[`Six`,`Eleven`,`Seven`],`Each basketball team has five players on the court; the others wait on the bench as substitutes.`],[3,2,`sports`,`In which sport is a puck hit into the goal?`,`Ice hockey`,[`Cricket`,`Tennis`,`Badminton`],`Players use curved sticks to hit a hard rubber puck across the ice.`],[3,2,`sports`,`A football match usually lasts 90 minutes, plus added time.`,`True`,[`False`],`Two halves of 45 minutes each, with extra minutes added for stoppages.`],[4,1,`sports`,`How often are the Summer Olympic Games usually held?`,`Every four years`,[`Every year`,`Every two years`,`Every ten years`],`The Summer and Winter Games take turns, two years apart.`],[4,2,`sports`,`In cricket, how many balls make up a standard over?`,`Six`,[`Four`,`Eight`,`Ten`],`After six legal deliveries, a different bowler bowls from the other end.`],[4,3,`sports`,`In which country did the game of cricket develop?`,`England`,[`India`,`Australia`,`South Africa`],`Cricket was played in England by the 1500s and spread across the British Empire.`],[5,1,`sports`,`Which chess piece can only move diagonally?`,`The bishop`,[`The rook`,`The knight`,`The king`],`Each bishop stays on squares of one colour for the whole game.`],[5,2,`sports`,`How long is a marathon race?`,`About 42.2 kilometres`,[`About 10 kilometres`,`About 21 kilometres`,`About 100 kilometres`],`The official distance is 42.195 km, the same distance Marathon GO counts towards.`],[5,3,`sports`,`Which sport uses the words 'love', 'deuce' and 'advantage' in its scoring?`,`Tennis`,[`Golf`,`Cricket`,`Volleyball`],`Love means zero; deuce means 40–40.`],[6,1,`sports`,`Which country won the first FIFA World Cup, in 1930?`,`Uruguay`,[`Brazil`,`Italy`,`Argentina`],`Uruguay hosted the first World Cup and beat Argentina in the final.`],[6,2,`sports`,`Kabaddi is the national game of which country?`,`Bangladesh`,[`Nepal`,`Sri Lanka`,`Bhutan`],`In Bangladesh kabaddi is also called hadudu: raiders tag opponents while holding their breath.`],[6,3,`sports`,`In which sport would you see a 'slam dunk'?`,`Basketball`,[`Volleyball`,`Rugby`,`Baseball`],`A slam dunk is when a player jumps and pushes the ball down through the hoop.`],[7,1,`sports`,`Which country has won the most men's FIFA World Cups?`,`Brazil`,[`Germany`,`Italy`,`Argentina`],`Brazil has won the World Cup five times.`],[7,2,`sports`,`In which year did Bangladesh's men's cricket team play their first Test match?`,`2000`,[`1986`,`1997`,`2005`],`Bangladesh played India in Dhaka in November 2000, its first Test as a full member of the ICC.`],[7,3,`sports`,`What is the highest score possible with three darts in one turn?`,`180`,[`100`,`150`,`300`],`Three darts in the treble 20 score 60 each: 180.`],[8,1,`sports`,`How many points is a touchdown worth in American football, before the extra point?`,`Six`,[`Three`,`Seven`,`Two`],`A field goal is worth three points; the kick after a touchdown usually adds one.`],[8,2,`sports`,`Which Olympic event combines ten track and field events over two days?`,`The decathlon`,[`The pentathlon`,`The triathlon`,`The heptathlon`],`The decathlon has ten events in which athletes run, jump and throw; the heptathlon has seven events.`],[8,3,`sports`,`Which tennis tournament is played on clay courts in Paris?`,`The French Open (Roland-Garros)`,[`Wimbledon`,`The US Open`,`The Australian Open`],`Clay makes the ball bounce higher and slower than on grass or hard courts.`],[3,1,`arts`,`Which instrument has strings and is played with a bow?`,`The violin`,[`The drum`,`The flute`,`The trumpet`],`Drawing the bow across the strings makes them vibrate.`],[3,2,`arts`,`What do we call a person who writes music?`,`A composer`,[`A sculptor`,`A poet`,`A painter`],`Composers write the music that performers play or sing.`],[4,1,`arts`,`What are the three primary colours used in painting?`,`Red, yellow and blue`,[`Green, orange and purple`,`Black, white and grey`,`Pink, brown and gold`],`Mixing pairs of primary colours makes the secondary colours: orange, green and purple.`],[4,2,`arts`,`Who wrote the fairy tale 'The Ugly Duckling'?`,`Hans Christian Andersen`,[`The Brothers Grimm`,`Charles Perrault`,`Aesop`],`Andersen, from Denmark, also wrote 'The Little Mermaid'.`],[4,3,`arts`,`What is a sculpture?`,`A 3D work of art carved or shaped from a material`,[`A painting on a flat canvas`,`A short piece of music`,`A poem with fourteen lines`],`Sculptors work in stone, wood, metal, clay and many other materials.`],[5,1,`arts`,`Nakshi kantha is a traditional Bangladeshi craft of what?`,`Embroidered quilts`,[`Clay pots`,`Brass statues`,`Woven baskets`],`Nakshi kantha quilts are stitched from old cloth with colourful patterns that tell stories.`],[5,2,`arts`,`Which famous composer kept writing music after becoming deaf?`,`Ludwig van Beethoven`,[`Wolfgang Amadeus Mozart`,`Johann Sebastian Bach`,`Frédéric Chopin`],`Beethoven wrote his Ninth Symphony when he was almost completely deaf.`],[5,3,`arts`,`Who wrote 'Alice's Adventures in Wonderland'?`,`Lewis Carroll`,[`Roald Dahl`,`Charles Dickens`,`Enid Blyton`],`The book was published in 1865.`],[5,2,`arts`,`The Mona Lisa hangs in the Louvre museum in Paris.`,`True`,[`False`],`Millions of people visit the Louvre every year to see it.`],[6,1,`arts`,`What is a tabla?`,`A pair of hand drums`,[`A kind of flute`,`A stringed lute`,`A brass horn`],`Tabla players use their fingers and palms to make many different sounds.`],[6,2,`arts`,`Who wrote the novel 'Oliver Twist'?`,`Charles Dickens`,[`Mark Twain`,`Jane Austen`,`Leo Tolstoy`],`Dickens wrote about the hard lives of poor children in Victorian London.`],[6,3,`arts`,`Which Bangladeshi artist is famous for his sketches of the Bengal famine of 1943?`,`Zainul Abedin`,[`S. M. Sultan`,`Rabindranath Tagore`,`Abanindranath Tagore`],`Zainul Abedin's black-ink famine drawings made him famous; he later helped found Dhaka's art college.`],[7,1,`arts`,`Which artist painted 'The Last Supper' on a wall in Milan in the 1490s?`,`Leonardo da Vinci`,[`Michelangelo`,`Raphael`,`Rembrandt`],`The mural is painted on the wall of a monastery dining hall.`],[7,2,`arts`,`Who composed 'The Four Seasons' violin concertos?`,`Antonio Vivaldi`,[`Ludwig van Beethoven`,`Johann Sebastian Bach`,`Pyotr Tchaikovsky`],`Vivaldi, a Venetian composer, published them in 1725.`],[7,3,`arts`,`In which Shakespeare play does a character ask, 'To be, or not to be'?`,`Hamlet`,[`Macbeth`,`Othello`,`King Lear`],`Prince Hamlet speaks the famous lines while thinking about life and death.`],[8,1,`arts`,`'Pride and Prejudice' (1813) is the best-known novel of which English writer?`,`Jane Austen`,[`Charlotte Brontë`,`George Eliot`,`Mary Shelley`],`Austen's novels are known for their wit and their portraits of family life.`],[8,2,`arts`,`Which art movement did Pablo Picasso help to start?`,`Cubism`,[`Impressionism`,`Surrealism`,`Pop art`],`Cubist paintings show objects from several viewpoints at once, in geometric shapes.`],[8,3,`arts`,`Who wrote the poem 'Bidrohi' ('The Rebel')?`,`Kazi Nazrul Islam`,[`Rabindranath Tagore`,`Jibanananda Das`,`Jasimuddin`],`Published in 1922, 'Bidrohi' made Nazrul famous as the rebel poet.`]],[[3,1,`world`,`How many hours are there in one day?`,`24`,[`12`,`60`,`100`],`A full day and night together last 24 hours, one turn of the Earth.`],[3,2,`history`,`Before money existed, people often swapped goods directly. What is this called?`,`Barter`,[`Banking`,`Taxing`,`Lending`],`A farmer might barter rice for a potter's pots.`],[3,3,`sports`,`In which sport do players hit a shuttlecock over a high net?`,`Badminton`,[`Tennis`,`Table tennis`,`Squash`],`A shuttlecock has feathers (or plastic) and a rounded cork base.`],[4,1,`inventions`,`What did people use to count and calculate by moving beads along rods?`,`An abacus`,[`A sundial`,`A compass`,`A loom`],`The abacus has been used for thousands of years and is still taught today.`],[4,1,`world`,`What colour are most road signs that tell drivers to stop?`,`Red`,[`Green`,`Blue`,`Yellow`],`Red is used around the world to mean stop or danger.`],[4,1,`arts`,`Which instrument do you blow across, with holes for your fingers?`,`The flute`,[`The drum`,`The violin`,`The piano`],`Covering and uncovering the holes changes the notes.`],[4,2,`history`,`Why was the Great Pyramid of Giza built?`,`As a tomb for a pharaoh`,[`As a palace to live in`,`As a temple to the Moon`,`As a lighthouse for ships`],`It was built for the pharaoh Khufu about 4,500 years ago.`],[4,2,`history`,`The ancient Egyptians made mummies to preserve the bodies of the dead.`,`True`,[`False`],`They believed the body was needed in the afterlife.`],[5,1,`history`,`Which metal gave its name to the age that followed the Stone Age?`,`Bronze`,[`Iron`,`Gold`,`Silver`],`People learned to mix copper and tin to make bronze tools; the Iron Age came after.`],[5,1,`sports`,`Which board game has kings, queens, rooks and pawns on 64 squares?`,`Chess`,[`Ludo`,`Draughts`,`Carrom`],`Chess began in India as chaturanga about 1,500 years ago.`],[5,2,`world`,`Which is the largest country in Africa by area?`,`Algeria`,[`Nigeria`,`Egypt`,`South Africa`],`Algeria became Africa's largest country in 2011, when South Sudan split from Sudan.`],[5,2,`arts`,`Mowgli is the hero of which book?`,`The Jungle Book`,[`Peter Pan`,`Treasure Island`,`Black Beauty`],`Rudyard Kipling's book tells of a boy raised by wolves in the Indian jungle.`],[5,3,`history`,`Which ship carried the Pilgrims from England to America in 1620?`,`The Mayflower`,[`The Titanic`,`The Santa María`,`HMS Victory`],`The Pilgrims founded Plymouth Colony in what is now Massachusetts.`],[6,1,`history`,`What were the Crusades?`,`Religious wars between Christian and Muslim armies in the Middle Ages`,[`A series of sea voyages to find India`,`Peace talks that ended the Mughal Empire`,`Races held at the first Olympic Games`],`The Crusades, from 1096 to the late 1200s, were fought largely over Jerusalem.`],[6,1,`inventions`,`Which inventor's phonograph of 1877 could record and play back sound?`,`Thomas Edison's`,[`Alexander Graham Bell's`,`Guglielmo Marconi's`,`Nikola Tesla's`],`The first words Edison recorded were 'Mary had a little lamb'.`],[6,2,`world`,`Which country has the largest population in Africa?`,`Nigeria`,[`Egypt`,`Ethiopia`,`Kenya`],`More than 200 million people live in Nigeria.`],[6,2,`history`,`Which nawab of Bengal lost the Battle of Plassey?`,`Siraj ud-Daulah`,[`Mir Jafar`,`Tipu Sultan`,`Alivardi Khan`],`Siraj ud-Daulah lost at Plassey in 1757; Mir Jafar, his commander, betrayed him and was made nawab by the British.`],[6,2,`arts`,`In which country did origami, the art of paper folding, become famous?`,`Japan`,[`Italy`,`Egypt`,`Brazil`],`Origami cranes are a symbol of peace and hope in Japan.`],[6,2,`inventions`,`The bicycle was invented before the car.`,`True`,[`False`],`Early bicycles appeared in the early 1800s; the first practical cars came in the 1880s.`],[6,2,`arts`,`An orchestra's string section includes violins and cellos.`,`True`,[`False`],`The strings also include violas and double basses.`],[6,3,`sports`,`In golf, what is one stroke under par on a hole called?`,`A birdie`,[`An eagle`,`A bogey`,`A par`],`One under par is a birdie. An eagle is two under par; a bogey is one over.`],[6,3,`inventions`,`Which father and son built the famous 'Rocket' steam locomotive of 1829?`,`George and Robert Stephenson`,[`James Watt and his son`,`The Wright brothers`,`Thomas Edison and his son`],`The Rocket won a contest to choose engines for the Liverpool and Manchester Railway.`],[6,3,`history`,`Bangladesh was known as East Pakistan before 1971.`,`True`,[`False`],`From 1947 to 1971 it was the eastern wing of Pakistan, about 1,600 km from the western wing.`],[7,1,`history`,`Which explorer was the first European to reach India by sea, in 1498?`,`Vasco da Gama`,[`Christopher Columbus`,`Ferdinand Magellan`,`James Cook`],`He sailed from Portugal around Africa's Cape of Good Hope to Calicut.`],[7,1,`sports`,`Which famous boxer said he could 'float like a butterfly, sting like a bee'?`,`Muhammad Ali`,[`Mike Tyson`,`Joe Frazier`,`George Foreman`],`Ali won the world heavyweight title three times.`],[7,1,`arts`,`Baul songs are a mystic folk music tradition of which region?`,`Bengal`,[`Kashmir`,`Punjab`,`Kerala`],`Lalon Shah is the most famous Baul poet-singer; Baul music is on UNESCO's list of intangible heritage.`],[7,2,`history`,`Whose expedition was the first to sail all the way around the world, in 1519–1522?`,`Ferdinand Magellan's`,[`Christopher Columbus's`,`Vasco da Gama's`,`James Cook's`],`Magellan died on the way; Juan Sebastián Elcano led the last ship home.`],[7,2,`world`,`On which continent is Vatican City, the smallest country in the world?`,`Europe`,[`Africa`,`Asia`,`South America`],`Vatican City lies inside the city of Rome, in Italy.`],[7,2,`sports`,`A cricket pitch is 22 yards long between the wickets.`,`True`,[`False`],`22 yards is about 20.1 metres.`],[7,3,`arts`,`Which epic poem by Homer tells of Odysseus's long journey home?`,`The Odyssey`,[`The Iliad`,`The Aeneid`,`The Mahabharata`],`The Odyssey tells of Odysseus's journey home. The Iliad, also by Homer, tells of the Trojan War.`],[8,1,`arts`,`Which ancient Indian epic tells the story of Rama?`,`The Ramayana`,[`The Mahabharata`,`The Shahnameh`,`The Odyssey`],`The Ramayana is traditionally credited to the poet Valmiki.`],[8,1,`sports`,`How many players from each team are on a volleyball court?`,`Six`,[`Five`,`Nine`,`Eleven`],`Six players rotate positions each time their team wins the serve.`],[8,2,`history`,`Which ancient empire was ruled from Persepolis?`,`The Persian (Achaemenid) Empire`,[`The Roman Empire`,`The Mughal Empire`,`The Inca Empire`],`Persepolis was a ceremonial capital; Alexander the Great burned it in 330 BC.`],[8,2,`world`,`What is the main language of Iran?`,`Persian (Farsi)`,[`Arabic`,`Turkish`,`Urdu`],`The main language of Iran is Persian (Farsi). It is written in a form of the Arabic script but is a different language.`],[8,2,`sports`,`Beijing hosted the Summer Olympics in which year?`,`2008`,[`2000`,`2012`,`2016`],`The Beijing Games opened on 8 August 2008 (8/8/08).`],[8,2,`arts`,`Which musical instrument did Ravi Shankar make famous around the world?`,`The sitar`,[`The tabla`,`The sarod`,`The flute`],`Shankar played with Western musicians such as George Harrison and Yehudi Menuhin.`],[8,3,`history`,`The Rosetta Stone helped scholars to read which ancient writing?`,`Egyptian hieroglyphs`,[`Sumerian cuneiform`,`Chinese oracle bones`,`Mayan glyphs`],`It carries the same text in hieroglyphs, Demotic and ancient Greek.`],[8,3,`arts`,`Which Persian poet wrote the 'Shahnameh' (Book of Kings)?`,`Ferdowsi`,[`Rumi`,`Hafez`,`Omar Khayyam`],`Ferdowsi finished the epic of about 50,000 couplets around the year 1010.`]],[[3,1,`history`,`What were castles mainly built for?`,`Defending the people inside`,[`Growing crops`,`Holding markets`,`Keeping animals warm`],`Thick walls, towers and moats made castles hard for enemies to attack.`],[3,2,`history`,`Long ago, before cars, what usually pulled carriages and carts?`,`Horses`,[`Elephants only`,`Dogs`,`Steam engines`],`For thousands of years horses, oxen and donkeys did the pulling.`],[3,3,`history`,`Some early humans painted animals on the walls of caves.`,`True`,[`False`],`Cave paintings in places such as Lascaux in France are more than 17,000 years old.`],[4,1,`history`,`In honour of which god were the ancient Olympic Games held?`,`Zeus`,[`Poseidon`,`Ra`,`Thor`],`The games took place at Olympia, at a great sanctuary of Zeus.`],[4,1,`history`,`What did the ancient Romans call the open square at the centre of a town, used for markets and meetings?`,`The forum`,[`The arena`,`The temple`,`The villa`],`The Roman Forum was the heart of public life in ancient Rome.`],[4,2,`history`,`Which of the Seven Wonders of the Ancient World is the only one still standing?`,`The Great Pyramid of Giza`,[`The Colossus of Rhodes`,`The Hanging Gardens of Babylon`,`The Lighthouse of Alexandria`],`Built about 4,500 years ago, the Great Pyramid is the oldest of the wonders and the only survivor.`],[4,2,`history`,`Who were gladiators?`,`Fighters who entertained crowds in ancient Rome`,[`Priests in ancient Egypt`,`Farmers in ancient China`,`Sailors in ancient Greece`],`Gladiators fought in arenas such as the Colosseum, often as slaves or prisoners.`],[4,3,`history`,`The Vikings sailed in long wooden ships called longships.`,`True`,[`False`],`Longships were fast and shallow, so they could cross seas and sail up rivers.`],[5,1,`history`,`Which Roman town was buried by the eruption of Mount Vesuvius in AD 79?`,`Pompeii`,[`Athens`,`Carthage`,`Troy`],`Ash preserved Pompeii so well that we can still walk its streets today.`],[5,1,`history`,`Which people built the great city of Tenochtitlan on a lake, where Mexico City is now?`,`The Aztecs`,[`The Inca`,`The Maya`,`The Romans`],`Tenochtitlan was the Aztec capital until the Spanish conquest in 1521.`],[5,2,`history`,`Which Mughal emperor built the Red Fort in Delhi?`,`Shah Jahan`,[`Babur`,`Akbar`,`Aurangzeb`],`Shah Jahan moved his capital to Delhi and built the Red Fort in the 1600s.`],[5,2,`history`,`Who was Joan of Arc?`,`A French peasant girl who led armies in the 1400s`,[`An English queen who built castles`,`A Spanish explorer who found gold`,`A Greek poet who wrote epics`],`She helped France during the Hundred Years' War and was later made a saint.`],[5,3,`history`,`Which queen ruled Britain for more than 63 years in the 1800s and early 1900s?`,`Queen Victoria`,[`Queen Elizabeth I`,`Queen Mary`,`Queen Anne`],`Victoria reigned from 1837 to 1901, and the period is called the Victorian age.`],[5,3,`history`,`The ancient Maya of Central America wrote with picture signs called glyphs and had a detailed calendar.`,`True`,[`False`],`Maya astronomers tracked the Sun, Moon and Venus with great accuracy.`],[6,1,`history`,`Which dynasty ruled Bengal from about the 8th century and built the great Buddhist monastery at Paharpur?`,`The Pala dynasty`,[`The Mughal dynasty`,`The Maurya dynasty`,`The Tudor dynasty`],`The Pala kings supported Buddhist learning for about four hundred years.`],[6,1,`history`,`Which machine, greatly improved by James Watt, powered factories in the Industrial Revolution?`,`The steam engine`,[`The petrol engine`,`The windmill`,`The electric motor`],`Watt's improvements in the 1760s and 1770s made steam engines far more efficient.`],[6,2,`history`,`What was apartheid?`,`A system of racial segregation in South Africa`,[`A trade route across Africa`,`A kind of ancient temple`,`A peace treaty after a war`],`Apartheid laws separated people by race from 1948 until the early 1990s.`],[6,2,`history`,`The Great Fire of London took place in 1666.`,`True`,[`False`],`The fire burned for about four days and destroyed much of the old city.`],[6,3,`history`,`In which year did Lord Curzon divide the province of Bengal, a partition later reversed?`,`1905`,[`1857`,`1947`,`1952`],`The partition of 1905 caused protests and was cancelled in 1911.`],[6,3,`history`,`Which female pharaoh built a great temple at Deir el-Bahari in Egypt?`,`Hatshepsut`,[`Cleopatra`,`Nefertiti`,`Isis`],`Hatshepsut ruled for about 20 years in the 15th century BC and was a great builder.`],[7,1,`history`,`The Hundred Years' War was fought mainly between England and which country?`,`France`,[`Spain`,`Scotland`,`Germany`],`It lasted, with breaks, from 1337 to 1453.`],[7,1,`history`,`Which empire did Suleiman the Magnificent rule in the 1500s?`,`The Ottoman Empire`,[`The Mughal Empire`,`The Roman Empire`,`The Persian Empire`],`Under Suleiman the Ottoman Empire reached its greatest power.`],[7,2,`history`,`What is remembered in Bangladesh on 16 December each year?`,`Victory Day, the end of the 1971 Liberation War`,[`The Bengali New Year`,`International Mother Language Day`,`The birth of the national poet`],`On 16 December 1971 the Pakistani army surrendered in Dhaka, and Bangladesh won the war.`],[7,2,`history`,`Who founded the Maurya Empire in ancient India?`,`Chandragupta Maurya`,[`Ashoka the Great`,`Akbar the Great`,`Harsha Vardhana`],`Chandragupta Maurya founded the empire in about 321 BC; his grandson Ashoka later ruled it.`],[7,3,`history`,`Which ancient city on the Euphrates is famous for its legendary Hanging Gardens?`,`Babylon`,[`Athens`,`Memphis`,`Persepolis`],`Babylon was a great city of Mesopotamia, in what is now Iraq.`],[7,3,`history`,`The American Declaration of Independence was signed in 1776.`,`True`,[`False`],`On 4 July 1776 thirteen colonies declared independence from Britain.`],[7,3,`history`,`Who led a peasant uprising against landlords and the British in Bengal and built a bamboo fort in 1831?`,`Titumir`,[`Siraj ud-Daulah`,`Tipu Sultan`,`Shah Jahan`],`Titumir's bamboo fort at Narkelberia was destroyed by British troops in 1831.`],[8,1,`history`,`Which revolution of 1917 brought the Bolsheviks to power?`,`The Russian Revolution`,[`The French Revolution`,`The American Revolution`,`The Glorious Revolution`],`Led by Lenin, the Bolsheviks took power in Russia in October 1917.`],[8,1,`history`,`After the Second World War, what was the Marshall Plan?`,`US aid to rebuild Western Europe after the Second World War`,[`A plan to land on the Moon`,`A Roman road-building plan`,`A treaty that ended the First World War`],`Between 1948 and 1952 the US gave billions of dollars to help European economies recover.`],[8,2,`history`,`What was the League of Nations?`,`A body set up after the First World War to keep peace`,[`A football league in Europe`,`A trading company in India`,`An alliance of ancient Greek cities`],`It was founded in 1920 but failed to stop the Second World War; the United Nations replaced it.`],[8,2,`history`,`Mahasthangarh, near Bogura, is the site of which ancient city?`,`Pundranagara`,[`Pataliputra`,`Gaur`,`Sonargaon`],`It is one of the oldest known city sites in Bangladesh, dating back to at least the 3rd century BC.`],[8,3,`history`,`Which revolutionary led an attack on a British club in Chattogram in 1932 and is remembered as a hero?`,`Pritilata Waddedar`,[`Begum Rokeya`,`Sufia Kamal`,`Jahanara Imam`],`Pritilata was part of the anti-British movement led by Surya Sen in Chattogram.`],[8,3,`history`,`Gandhi's Salt March, a protest against British salt taxes, took place in 1930.`,`True`,[`False`],`Gandhi and his followers walked about 390 km to the sea at Dandi to make salt.`],[3,1,`inventions`,`Which invention helps people whose eyes are weak to see clearly?`,`Glasses (spectacles)`,[`A telescope for stars`,`A camera`,`A torch`],`Lenses in glasses bend light so that it focuses properly in the eye.`],[3,2,`inventions`,`What does a refrigerator do?`,`Keeps food cold so it stays fresh`,[`Cooks food quickly`,`Washes the dishes`,`Makes bread rise`],`Cold slows the growth of the germs that make food go bad.`],[3,3,`inventions`,`The wheel is a very old invention, more than 5,000 years old.`,`True`,[`False`],`The first wheels were used in Mesopotamia, at first for making pots and then for carts.`],[4,1,`inventions`,`What did the Chinese invent that was first used in fireworks?`,`Gunpowder`,[`Paper`,`Silk`,`Porcelain`],`Gunpowder was discovered in China over a thousand years ago.`],[4,2,`inventions`,`Which Italian inventor sent radio signals across the Atlantic Ocean in 1901?`,`Guglielmo Marconi`,[`Galileo Galilei`,`Alessandro Volta`,`Leonardo da Vinci`],`Marconi developed long-distance radio and shared the 1909 Nobel Prize in Physics.`],[4,2,`inventions`,`Who gave the first public demonstration of a working television, in 1926?`,`John Logie Baird`,[`Thomas Edison`,`Alexander Graham Bell`,`Nikola Tesla`],`The Scottish inventor Baird showed moving pictures on a mechanical television in London.`],[4,3,`inventions`,`In 1783 the Montgolfier brothers' invention first carried people into the air. What was it?`,`A hot-air balloon`,[`An aeroplane`,`A helicopter`,`A glider`],`Their balloon rose over Paris, 120 years before the Wright brothers' powered flight.`],[5,1,`inventions`,`What did Samuel Morse invent for sending messages by telegraph?`,`A code of dots and dashes`,[`The telephone`,`The typewriter`,`A sign language`],`Morse code turns letters into short and long signals.`],[5,2,`inventions`,`Which two elements did Marie Curie discover?`,`Polonium and radium`,[`Oxygen and hydrogen`,`Gold and silver`,`Carbon and iron`],`She named polonium after her homeland, Poland.`],[5,3,`inventions`,`The earliest photographs needed people to keep still for minutes at a time.`,`True`,[`False`],`Early cameras needed long exposures, which is why people in old photos rarely smile.`],[6,1,`inventions`,`Which British engineer patented a design for the jet engine in 1930?`,`Frank Whittle`,[`James Watt`,`Isambard Brunel`,`Charles Babbage`],`Whittle's jet engines powered British aircraft from 1941; Hans von Ohain worked on jets in Germany at the same time.`],[6,2,`inventions`,`What did Michael Faraday show in 1831 that led to electric generators?`,`A moving magnet can make electricity`,[`Light is made of colours`,`Germs cause disease`,`The Earth goes round the Sun`],`This effect, electromagnetic induction, is how power stations generate electricity today.`],[6,2,`inventions`,`Which scholar of the 1200s, from Upper Mesopotamia, designed water clocks and early robot-like machines?`,`Al-Jazari`,[`Ibn Battuta`,`Omar Khayyam`,`Al-Biruni`],`His Book of Knowledge of Ingenious Mechanical Devices (about 1206) describes some fifty machines.`],[6,3,`inventions`,`The first call on a handheld mobile phone was made in 1973.`,`True`,[`False`],`Martin Cooper of Motorola made the call in New York; the phone weighed about 1 kg.`],[7,1,`inventions`,`Who invented the stethoscope, in 1816?`,`René Laennec`,[`Louis Pasteur`,`Edward Jenner`,`Joseph Lister`],`The French doctor Laennec first used a rolled-up paper tube to listen to a patient's heart.`],[7,2,`inventions`,`Which doctor showed in the 1840s that washing hands saved mothers' lives in hospital?`,`Ignaz Semmelweis`,[`Joseph Lister`,`Robert Koch`,`William Harvey`],`Semmelweis cut deaths sharply by making doctors wash their hands, though many ignored him at the time.`],[7,2,`inventions`,`Who first used insulin to treat diabetes successfully, in 1921–22?`,`Frederick Banting and Charles Best`,[`Watson and Crick`,`Marie and Pierre Curie`,`The Wright brothers`],`Their work in Toronto turned diabetes from a deadly disease into one people could live with.`],[7,3,`inventions`,`The internet grew out of ARPANET, a US research network from 1969.`,`True`,[`False`],`ARPANET linked university computers; its methods became the basis of the internet.`],[8,1,`inventions`,`Which tiny electronic switch was invented at Bell Labs in 1947 and made modern computers possible?`,`The transistor`,[`The valve`,`The microchip`,`The battery`],`John Bardeen, Walter Brattain and William Shockley shared a Nobel Prize for it.`],[8,2,`inventions`,`Which actor and inventor co-designed a ‘frequency-hopping’ radio system that later helped Wi-Fi and Bluetooth?`,`Hedy Lamarr`,[`Marie Curie`,`Ada Lovelace`,`Grace Hopper`],`Lamarr and George Antheil patented the idea in 1942.`],[8,2,`inventions`,`Whose team built the first nuclear reactor, Chicago Pile-1, in 1942?`,`Enrico Fermi's`,[`Albert Einstein's`,`Niels Bohr's`,`Ernest Rutherford's`],`The reactor showed that a controlled nuclear chain reaction was possible.`],[8,3,`inventions`,`Penicillin was discovered partly by accident, from mould on a forgotten dish of bacteria.`,`True`,[`False`],`In 1928 Alexander Fleming noticed that the mould had killed the bacteria around it.`],[3,1,`people`,`Who was the first Bangladeshi to reach the summit of Mount Everest, in 2010?`,`Musa Ibrahim`,[`Edmund Hillary`,`Tenzing Norgay`,`Neil Armstrong`],`Musa Ibrahim reached the top on 23 May 2010.`],[3,2,`people`,`Jane Goodall became famous for studying which animals in the wild?`,`Chimpanzees`,[`Penguins`,`Tigers`,`Whales`],`She watched chimpanzees in Tanzania for decades and showed that they make and use tools.`],[3,3,`people`,`Nelson Mandela became the President of South Africa in 1994.`,`True`,[`False`],`He had spent 27 years in prison before becoming the country's first Black president.`],[4,1,`people`,`Who was the first woman to fly solo across the Atlantic Ocean, in 1932?`,`Amelia Earhart`,[`Valentina Tereshkova`,`Marie Curie`,`Florence Nightingale`],`Earhart flew from Newfoundland to Northern Ireland in about 15 hours.`],[4,2,`people`,`Whose refusal to give up her bus seat in 1955 helped start the US civil rights movement?`,`Rosa Parks`,[`Harriet Tubman`,`Maya Angelou`,`Michelle Obama`],`Her arrest in Montgomery, Alabama, led to a year-long bus boycott.`],[4,3,`people`,`Who was the first Bangladeshi woman to climb Mount Everest, in 2012?`,`Nishat Majumdar`,[`Begum Rokeya`,`Sufia Kamal`,`Selina Hossain`],`Nishat Majumdar reached the summit on 19 May 2012.`],[5,1,`people`,`Helen Keller, who could neither see nor hear, became famous as…`,`an author and campaigner`,[`a racing driver`,`a painter of landscapes`,`a film star`],`With her teacher Anne Sullivan she learned to communicate and went on to write books and give talks.`],[5,2,`people`,`Who made the first ever spacewalk, in 1965?`,`Alexei Leonov`,[`Neil Armstrong`,`Yuri Gagarin`,`John Glenn`],`Leonov floated outside his spacecraft for about 12 minutes.`],[5,3,`people`,`Which Bengali film-maker made ‘Pather Panchali’, about a poor village family?`,`Satyajit Ray`,[`Ritwik Ghatak`,`Zahir Raihan`,`Raj Kapoor`],`Released in 1955, it was the first part of Ray's Apu Trilogy.`],[6,1,`people`,`Which Bangladeshi-born engineer designed Chicago's Sears Tower (now Willis Tower)?`,`Fazlur Rahman Khan`,[`Louis Kahn`,`Muzharul Islam`,`Fazle Hasan Abed`],`Fazlur Rahman Khan invented the ‘tube’ systems that made very tall skyscrapers practical.`],[6,2,`people`,`Kalpana Chawla is remembered as the first woman of Indian origin to…`,`go into space`,[`climb Mount Everest`,`win an Olympic gold`,`become a prime minister`],`She flew on the Space Shuttle in 1997 and died in the Columbia disaster in 2003.`],[6,3,`people`,`Who founded BRAC, one of the world's largest development organisations, in 1972?`,`Fazle Hasan Abed`,[`Muhammad Yunus`,`Fazlur Rahman Khan`,`Jagadish Chandra Bose`],`BRAC began helping refugees after the 1971 war and now works in many countries.`],[7,1,`people`,`Which physicist studied black holes and wrote ‘A Brief History of Time’?`,`Stephen Hawking`,[`Isaac Newton`,`Niels Bohr`,`Carl Sagan`],`Hawking did his work despite motor neurone disease, which left him almost completely paralysed.`],[7,2,`people`,`Which scholar of the 11th century is called a father of optics and of testing ideas by experiment?`,`Ibn al-Haytham`,[`Ibn Battuta`,`Al-Idrisi`,`Ibn Rushd`],`His Book of Optics explained that we see when light enters the eye.`],[7,3,`people`,`Who started Kenya's Green Belt Movement, which planted tens of millions of trees?`,`Wangari Maathai`,[`Jane Goodall`,`Rachel Carson`,`Malala Yousafzai`],`In 2004 she became the first African woman to win the Nobel Peace Prize.`],[8,1,`people`,`Which astrophysicist, Nobel Prize 1983, showed how heavy a star can be before it collapses?`,`Subrahmanyan Chandrasekhar`,[`Meghnad Saha`,`Homi J. Bhabha`,`Jayant Narlikar`],`The ‘Chandrasekhar limit’ is about 1.4 times the mass of the Sun.`],[8,2,`people`,`Which North African historian of the 1300s wrote the ‘Muqaddimah’, an early study of how societies rise and fall?`,`Ibn Khaldun`,[`Ibn Sina`,`Al-Khwarizmi`,`Rumi`],`Ibn Khaldun is often called a founder of sociology and of economic history.`],[8,3,`people`,`Rachel Carson's book ‘Silent Spring’ (1962) warned about the dangers of…`,`pesticides such as DDT`,[`nuclear weapons`,`plastic in the sea`,`cutting down rainforests`],`Her book helped start the modern environmental movement.`]],[[3,1,`world`,`Which number do you call in Bangladesh for police, fire or ambulance in an emergency?`,`999`,[`100`,`123`,`555`],`999 is Bangladesh's National Emergency Service number.`],[3,2,`world`,`At traffic lights, what does a green light tell drivers?`,`They may go`,[`They must stop`,`They must reverse`,`They must park`],`Green means go when it is safe; red means stop and amber means get ready to stop.`],[3,3,`world`,`A white flag waved in a battle usually means surrender or a wish to talk.`,`True`,[`False`],`For centuries a white flag has asked the other side to stop fighting.`],[4,1,`world`,`What do we call a country ruled by a king or a queen?`,`A monarchy`,[`A republic`,`A colony`,`A desert`],`In a monarchy the head of state inherits the position.`],[4,2,`world`,`Who usually leads the council of a city or town?`,`A mayor`,[`A judge`,`A general`,`A captain`],`Many cities choose a mayor to lead the local government.`],[4,3,`world`,`On which date is International Women's Day celebrated?`,`8 March`,[`1 May`,`21 February`,`25 December`],`It celebrates women's achievements and calls for equal rights.`],[5,1,`world`,`In which city is the Nobel Peace Prize presented?`,`Oslo`,[`Stockholm`,`Geneva`,`Paris`],`The other Nobel Prizes are presented in Stockholm, but the Peace Prize is given in Oslo, Norway.`],[5,2,`world`,`On which day each year is World Environment Day held?`,`5 June`,[`22 April`,`1 January`,`16 December`],`The United Nations has marked World Environment Day on 5 June since 1974.`],[5,2,`world`,`In which city are most of the European Union's main institutions based?`,`Brussels`,[`London`,`Rome`,`Vienna`],`The European Commission and the Council of the EU meet in Brussels, Belgium.`],[5,3,`world`,`What is a democracy?`,`A system where people choose their government by voting`,[`A system ruled by one family forever`,`A system where the army rules`,`A system with no laws at all`],`Demos is Greek for ‘the people’ and kratos means ‘power’ or ‘rule’.`],[6,1,`world`,`In which Dutch city does the International Court of Justice sit?`,`The Hague`,[`Amsterdam`,`Rotterdam`,`Brussels`],`The ICJ, the main court of the UN, settles disputes between countries.`],[6,2,`world`,`What do UN peacekeepers do?`,`Help keep the peace in places after conflict`,[`Collect taxes for the UN`,`Run the Olympic Games`,`Build space rockets`],`Bangladesh has long been one of the largest contributors of troops and police to UN peacekeeping.`],[6,2,`world`,`Which description fits Interpol?`,`A body that helps police of different countries work together`,[`A league for the world's football clubs`,`An international bank for poor countries`,`A company that builds motorways`],`Interpol is based in Lyon, France, and has about 195 member countries.`],[6,3,`world`,`A constitution is the basic set of laws and principles by which a country is governed.`,`True`,[`False`],`Bangladesh's constitution was adopted in 1972.`],[7,1,`world`,`What does inflation mean in economics?`,`A general rise in prices over time`,[`Blowing up balloons`,`A fall in the number of jobs`,`A rise in the value of money`],`With inflation, the same money buys less than it did before.`],[7,2,`world`,`What do the letters NGO usually stand for?`,`Non-governmental organisation`,[`National government office`,`New global order`,`Northern growth organisation`],`NGOs, such as charities, work for public good but are not part of a government.`],[7,3,`world`,`What is a referendum?`,`A vote by all citizens on one particular question`,[`A meeting of world leaders`,`A kind of court case`,`A list of all the voters`],`For example, a country might hold a referendum on changing its constitution.`],[8,1,`world`,`What is the main purpose of the Paris Agreement of 2015?`,`To limit global warming`,[`To set the rules of world trade`,`To end the Cold War`,`To organise the Olympic Games`],`Countries agreed to try to keep warming well below 2 °C above pre-industrial levels.`],[8,2,`world`,`What does the International Monetary Fund (IMF) mainly do?`,`Keeps the world money system stable and lends to countries`,[`Prints all of the world's banknotes`,`Runs the United Nations General Assembly`,`Sets the rules of international football`],`The IMF was set up in 1944 and has 190 or so member countries.`],[8,3,`world`,`What is the G20?`,`A forum of the world's major economies`,[`Twenty of the world's tallest buildings`,`A group of twenty football clubs`,`A satellite network`],`It brings together leaders of 19 countries, the European Union and the African Union.`],[3,1,`sports`,`Which sport is played with a bat, a ball and two sets of wickets?`,`Cricket`,[`Tennis`,`Hockey`,`Golf`],`Bowlers try to hit the wickets, and batters defend them.`],[3,2,`sports`,`Butterfly, backstroke and breaststroke are styles in which sport?`,`Swimming`,[`Running`,`Cycling`,`Boxing`],`Freestyle is the fourth stroke used in swimming races.`],[3,3,`sports`,`The Tour de France is a famous race for cyclists.`,`True`,[`False`],`The race lasts about three weeks and covers more than 3,000 km.`],[4,1,`sports`,`Which chess piece moves in an L-shape and can jump over other pieces?`,`The knight`,[`The rook`,`The queen`,`The king`],`The knight is the only piece that can leap over others.`],[4,2,`sports`,`In which sport do players score a ‘try’ by placing the ball down over the line?`,`Rugby`,[`Football`,`Basketball`,`Volleyball`],`A try is worth 5 points in rugby union.`],[4,3,`sports`,`Which bat-and-ball game, popular in the USA and Japan, has pitchers and home runs?`,`Baseball`,[`Cricket`,`Hockey`,`Tennis`],`A home run is a hit that lets the batter run round all four bases.`],[5,1,`sports`,`How many holes are played in a standard round of golf?`,`18`,[`9`,`12`,`36`],`Many courses have 18 holes; a short course may have 9 played twice.`],[5,1,`sports`,`In karate and judo, which belt colour shows an expert?`,`Black`,[`White`,`Yellow`,`Green`],`Beginners start with a white belt and work towards black.`],[5,2,`sports`,`In which city were the first modern Olympic Games held, in 1896?`,`Athens`,[`Paris`,`London`,`Rome`],`The games returned to Greece, where the ancient Olympics began.`],[5,2,`sports`,`In table tennis, a game is normally won by the first player to reach how many points (with a two-point lead)?`,`11`,[`21`,`15`,`10`],`Games went to 21 points until the rules changed in 2001.`],[5,3,`sports`,`In kabaddi, what must a raider do while in the other team's half?`,`Keep saying ‘kabaddi’ in a single breath`,[`Hop on one leg`,`Carry a ball`,`Keep their eyes closed`],`The raider must tag opponents and return before running out of breath.`],[6,1,`sports`,`In cricket, what do the letters LBW stand for?`,`Leg before wicket`,[`Long ball wide`,`Last batter walks`,`Low bounce wicket`],`A batter can be out LBW if the ball would have hit the stumps but struck their leg instead.`],[6,1,`sports`,`In football, what does a red card mean?`,`The player is sent off`,[`The player scored a goal`,`The game is over`,`The player gets a free kick`],`A sent-off player cannot be replaced, so the team plays with one fewer.`],[6,2,`sports`,`Which country won the 2022 FIFA World Cup in Qatar?`,`Argentina`,[`France`,`Brazil`,`Croatia`],`Argentina beat France on penalties after a 3–3 draw in the final.`],[6,2,`sports`,`How long is an Olympic swimming pool?`,`50 metres`,[`25 metres`,`100 metres`,`75 metres`],`Long-course pools for the Olympics are 50 m long with 8 or 10 lanes.`],[6,3,`sports`,`In cricket, what is a hat-trick?`,`Three wickets with three balls in a row by one bowler`,[`Three sixes in an over`,`Three catches by one fielder`,`Three runs from one ball`],`A bowler who takes wickets with three consecutive deliveries scores a hat-trick.`],[7,1,`sports`,`The Ashes is a famous cricket series between England and which country?`,`Australia`,[`India`,`South Africa`,`New Zealand`],`It began in 1882; the prize is a tiny urn said to hold the ashes of a burnt cricket bail.`],[7,1,`sports`,`The 2018 football World Cup was played in which country?`,`Russia`,[`Brazil`,`Germany`,`Japan`],`France won the 2018 tournament, beating Croatia in the final.`],[7,2,`sports`,`What is the highest possible break in snooker (without fouls)?`,`147`,[`100`,`180`,`155`],`15 reds each followed by the black, then all the colours: 15 × 8 + 27 = 147.`],[7,3,`sports`,`What is a steeplechase in athletics?`,`A running race with barriers and a water jump`,[`A relay race of four runners`,`A race walked rather than run`,`A jump over a single high bar`],`The 3,000 m steeplechase has 28 barrier jumps and 7 water jumps.`],[8,1,`sports`,`Which city will host the 2028 Summer Olympics?`,`Los Angeles`,[`Brisbane`,`Paris`,`Tokyo`],`Los Angeles is hosting for the third time, after 1932 and 1984; Brisbane hosts in 2032.`],[8,2,`sports`,`What is the Duckworth–Lewis–Stern method used for?`,`Setting targets in rain-shortened cricket matches`,[`Ranking the world's tennis players`,`Timing laps in Formula 1 races`,`Scoring routines in gymnastics`],`It adjusts the target fairly when overs are lost to rain.`],[8,2,`sports`,`How many events make up the women's heptathlon?`,`7`,[`5`,`10`,`8`],`Hepta means seven: hurdles, high jump, shot put, 200 m, long jump, javelin and 800 m.`],[8,3,`sports`,`In football, what does VAR stand for?`,`Video assistant referee`,[`Very active runner`,`Valid attack rule`,`Visual area ruling`],`Officials watching replays advise the referee on goals, penalties and red cards.`],[3,1,`arts`,`Who leads an orchestra, standing in front of it with a baton?`,`The conductor`,[`The composer`,`The drummer`,`The singer`],`The conductor sets the speed and helps all the players keep together.`],[3,2,`arts`,`Who wrote and illustrated ‘The Very Hungry Caterpillar’?`,`Eric Carle`,[`Roald Dahl`,`Dr. Seuss`,`Beatrix Potter`],`The book, first published in 1969, has holes where the caterpillar has eaten through the pages.`],[3,3,`arts`,`A guitar usually has six strings.`,`True`,[`False`],`Most guitars have six strings; bass guitars usually have four.`],[4,1,`arts`,`Which author created Willy Wonka in ‘Charlie and the Chocolate Factory’?`,`Roald Dahl`,[`J.K. Rowling`,`Enid Blyton`,`C. S. Lewis`],`Roald Dahl also wrote ‘Matilda’ and ‘The BFG’.`],[4,2,`arts`,`What is a mural?`,`A large painting made directly on a wall`,[`A small portrait in a locket`,`A statue made of clay`,`A song for a festival`],`Murals can cover whole buildings.`],[4,3,`arts`,`What do we call a picture an artist makes of themselves?`,`A self-portrait`,[`A landscape`,`A still life`,`A cartoon strip`],`Rembrandt and Frida Kahlo painted many self-portraits.`],[5,1,`arts`,`Which Norwegian artist painted ‘The Scream’?`,`Edvard Munch`,[`Vincent van Gogh`,`Claude Monet`,`Salvador Dalí`],`The Norwegian artist Munch made several versions of it, starting in 1893.`],[5,2,`arts`,`Which American author wrote about the adventures of Tom Sawyer and Huckleberry Finn?`,`Mark Twain`,[`Charles Dickens`,`Lewis Carroll`,`Jules Verne`],`Mark Twain was the pen name of Samuel Clemens.`],[5,3,`arts`,`Jamdani is a traditional Bangladeshi…`,`finely woven muslin cloth, often made into saris`,[`kind of sweet made from milk`,`boat used on rivers`,`drum played at weddings`],`UNESCO lists the art of Jamdani weaving as Intangible Cultural Heritage.`],[6,1,`arts`,`Which Dutch painter of the 1600s made ‘Girl with a Pearl Earring’?`,`Johannes Vermeer`,[`Rembrandt`,`Leonardo da Vinci`,`Pablo Picasso`],`The Dutch painter Vermeer painted it around 1665.`],[6,2,`arts`,`Which composer wrote the opera ‘The Magic Flute’ and was composing music by the age of five?`,`Wolfgang Amadeus Mozart`,[`Johann Sebastian Bach`,`Ludwig van Beethoven`,`Antonio Vivaldi`],`Mozart, from Salzburg, wrote over 600 works before he died aged 35.`],[6,2,`arts`,`Which Scottish author wrote the pirate adventure ‘Treasure Island’?`,`Robert Louis Stevenson`,[`Daniel Defoe`,`Jonathan Swift`,`Rudyard Kipling`],`The pirate Long John Silver first appeared in this 1883 novel.`],[6,3,`arts`,`Lalon Shah (Lalon Fakir) is famous for songs in which tradition?`,`Baul`,[`Opera`,`Jazz`,`Qawwali`],`Lalon's mystic songs about humanity are among the best-known Baul songs.`],[6,3,`arts`,`Rickshaw painting from Dhaka is listed by UNESCO as Intangible Cultural Heritage.`,`True`,[`False`],`The bright hand-painted designs on rickshaws were added to UNESCO's list in 2023.`],[7,1,`arts`,`Which painting by Pablo Picasso shows the bombing of a Spanish town in 1937?`,`Guernica`,[`The Starry Night`,`The Night Watch`,`The Persistence of Memory`],`Guernica's huge black-and-white canvas is a powerful protest against war.`],[7,1,`arts`,`Who wrote ‘Don Quixote’, about a man who imagines he is a knight?`,`Miguel de Cervantes`,[`William Shakespeare`,`Dante Alighieri`,`Victor Hugo`],`Its first part was published in 1605 and is often called the first modern novel.`],[7,2,`arts`,`Which Bangladeshi artist is famous for paintings of strong, muscular farmers of rural Bengal?`,`S. M. Sultan`,[`Zainul Abedin`,`Quamrul Hassan`,`Rafiqun Nabi`],`Sultan, from Narail, painted villagers as powerful heroes.`],[7,3,`arts`,`Who wrote ‘Things Fall Apart’ (1958), a classic novel about Nigeria?`,`Chinua Achebe`,[`Wole Soyinka`,`Ngũgĩ wa Thiong'o`,`Ben Okri`],`It tells the story of Okonkwo and the arrival of colonial rule.`],[8,1,`arts`,`Who wrote ‘Animal Farm’ and ‘Nineteen Eighty-Four’?`,`George Orwell`,[`Aldous Huxley`,`H. G. Wells`,`Charles Dickens`],`Orwell's books warn against tyranny and propaganda.`],[8,1,`arts`,`Which artist painted ‘The Persistence of Memory’, with its melting clocks?`,`Salvador Dalí`,[`René Magritte`,`Henri Matisse`,`Claude Monet`],`Dalí was a leading Surrealist painter.`],[8,2,`arts`,`In Bengali music, what is Rabindra Sangeet?`,`Songs written and composed by Rabindranath Tagore`,[`A dance from Manipur`,`A style of Bengali cooking`,`A type of folk drum`],`Tagore wrote over 2,000 songs, including the national anthems of Bangladesh and India.`],[8,2,`arts`,`Which Russian author wrote the long novel ‘War and Peace’?`,`Leo Tolstoy`,[`Fyodor Dostoevsky`,`Anton Chekhov`,`Alexander Pushkin`],`It follows Russian families during Napoleon's invasion of 1812.`],[8,3,`arts`,`Which Japanese artist made the woodblock print ‘The Great Wave off Kanagawa’?`,`Hokusai`,[`Hiroshige`,`Utamaro`,`Yoshitoshi`],`Mount Fuji can be seen small in the distance beneath the huge wave.`],[8,3,`arts`,`Which novel by Syed Waliullah, translated as ‘Tree Without Roots’, is a classic of Bangladeshi literature?`,`Lalsalu`,[`Padma Nadir Majhi`,`Pather Panchali`,`Devdas`],`Lalsalu (1948) shows how a man uses a false shrine to gain power in a village.`],[3,1,`general`,`What is a male deer called?`,`A stag`,[`A doe`,`A fawn`,`A calf`],`A male deer is a stag (or buck), a female is a doe and a baby is a fawn.`],[3,2,`general`,`What is a baby kangaroo called?`,`A joey`,[`A kid`,`A cub`,`A calf`],`A joey lives in its mother's pouch for months after it is born.`],[3,3,`general`,`Which festival marks the end of the month of Ramadan?`,`Eid al-Fitr`,[`Diwali`,`Christmas`,`Pohela Boishakh`],`Eid al-Fitr is celebrated with prayers, new clothes and visits to family.`],[4,1,`general`,`Which festival do Bengali Hindus celebrate in honour of the goddess Durga?`,`Durga Puja`,[`Holi`,`Eid al-Adha`,`Buddha Purnima`],`Durga Puja lasts several days, with decorated pandals and immersion of the image at the end.`],[4,2,`general`,`A word or phrase that reads the same backwards as forwards, like ‘level’, is called a…`,`palindrome`,[`synonym`,`rhyme`,`riddle`],`Racecar, noon and madam are palindromes too.`],[4,3,`general`,`Chinese New Year is also known as the…`,`Spring Festival`,[`Lantern Parade`,`Harvest Moon`,`Winter Feast`],`It falls between late January and mid-February, at the start of the Chinese lunar year.`],[5,1,`general`,`Which kind of scientist studies and forecasts the weather?`,`A meteorologist`,[`A geologist`,`A botanist`,`An astronomer`],`Meteorology is the science of the atmosphere and weather.`],[5,2,`general`,`Someone who studies rocks and how the Earth was formed is a…`,`geologist`,[`zoologist`,`chemist`,`historian`],`Geo means Earth; geologists study rocks, minerals and landforms.`],[5,3,`general`,`Which is the only letter that does not appear in the name of any US state?`,`Q`,[`Z`,`X`,`J`],`Every other letter of the alphabet appears in at least one state's name.`],[6,1,`general`,`What is a group of crows sometimes called?`,`A murder`,[`A parliament`,`A gaggle`,`A swarm`],`‘A murder of crows’ is one of many colourful old collective nouns, like a parliament of owls.`],[6,2,`general`,`How many players are there on each side in a game of chess?`,`One`,[`Two`,`Sixteen`,`Four`],`Each player controls 16 pieces of one colour.`],[6,3,`general`,`Which is the most common blood group in the world?`,`O`,[`A`,`B`,`AB`],`Group O is the most common overall, though the mix varies from country to country.`],[7,1,`general`,`Which planet is named after the Roman god of war?`,`Mars`,[`Jupiter`,`Saturn`,`Mercury`],`Its red colour reminded people of blood and battle.`],[7,2,`general`,`Braille readers feel patterns of raised dots. How many dot positions make up one Braille cell?`,`6`,[`4`,`8`,`10`],`A Braille cell has two columns of three dots, giving 64 possible patterns.`],[7,3,`general`,`The Olympic motto is ‘Faster, Higher, Stronger – Together’.`,`True`,[`False`],`The word ‘Together’ was added to the Latin ‘Citius, Altius, Fortius’ in 2021.`],[8,1,`general`,`Which calendar, used across most of the world today, was introduced by Pope Gregory XIII in 1582?`,`The Gregorian calendar`,[`The Julian calendar`,`The Bengali calendar`,`The Chinese calendar`],`The Gregorian calendar corrected the Julian calendar, which had drifted by about ten days.`],[8,2,`general`,`What does the Latin phrase ‘carpe diem’ mean?`,`Seize the day`,[`Time flies`,`Know yourself`,`Peace be with you`],`The poet Horace used it to urge people to enjoy the present.`],[8,3,`general`,`Which is the world's most translated document?`,`The Universal Declaration of Human Rights`,[`The Treaty of Versailles`,`The Magna Carta`,`The Olympic Charter`],`It has been translated into more than 500 languages.`]]],i=[...e(`gk`,n),...r.flatMap(e=>t(`gk`,e))];export{i as QUESTIONS};